package ocifetch

// revocation_statement_test.go — the shared revocation-statement table
// (tests/fixtures/revocation-statement/cases.json), generated by the delivery
// side's registry tests and read by all four bindings: which signed
// revocation statements count (docs/guides/fetch-v1.md, "Build-level
// revocation", rule 5) and that the first verifying revocation in a listing
// wins. The statement rows call verifyRevocation; the listing rows drive the
// real candidate loop through CheckInstalled against a local registry.

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
)

type statementAdvisory struct {
	ID           string `json:"id"`
	URL          string `json:"url"`
	Class        string `json:"class"`
	Summary      string `json:"summary"`
	SupersededBy string `json:"superseded_by"`
	RevokedAt    string `json:"revoked_at"`
}

type statementCase struct {
	Name           string            `json:"name"`
	Bundle         string            `json:"bundle"`
	Expect         string            `json:"expect"`
	ExpectAdvisory statementAdvisory `json:"expect_advisory"`
}

type statementListing struct {
	Name           string            `json:"name"`
	Referrers      []string          `json:"referrers"`
	Expect         string            `json:"expect"`
	RevokedBy      string            `json:"revoked_by"`
	ExpectAdvisory statementAdvisory `json:"expect_advisory"`
	Ignored        []string          `json:"ignored"`
	DontCare       []string          `json:"dont_care"`
}

type statementBuild struct {
	Manifest  Digest         `json:"manifest"`
	Layer     Digest         `json:"layer"`
	Predicate map[string]any `json:"predicate"`
}

// loadStatementTable reads the table, or skips LOUDLY when it is not beside
// this checkout, and refuses a table with no rows.
func loadStatementTable(t *testing.T) (dir string, key string, build statementBuild, cases []statementCase, listings []statementListing) {
	t.Helper()
	dir = filepath.Join("..", "..", "..", "tests", "fixtures", "revocation-statement")
	raw, err := os.ReadFile(filepath.Join(dir, "cases.json"))
	if err != nil {
		t.Skipf("SKIPPED: the shared revocation-statement table is not beside this checkout (%v)", err)
	}
	var doc struct {
		Cases    []statementCase    `json:"cases"`
		Listings []statementListing `json:"listings"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	if len(doc.Cases) == 0 || len(doc.Listings) == 0 {
		t.Fatalf("the revocation-statement table has %d cases and %d listings: the comparison would check nothing", len(doc.Cases), len(doc.Listings))
	}
	kb, err := os.ReadFile(filepath.Join(dir, "key.pub.hex"))
	if err != nil {
		t.Fatal(err)
	}
	bb, err := os.ReadFile(filepath.Join(dir, "build.predicate.json"))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(bb, &build); err != nil {
		t.Fatal(err)
	}
	return dir, strings.TrimSpace(string(kb)), build, doc.Cases, doc.Listings
}

func statementBundle(t *testing.T, dir, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func advisoryOf(a Advisory) statementAdvisory {
	return statementAdvisory{ID: a.ID, URL: a.URL, Class: a.Class, Summary: a.Summary, SupersededBy: a.SupersededBy, RevokedAt: a.RevokedAt}
}

// TestRevocationStatementTable: every single-statement row through
// verifyRevocation, under the fixture key alone.
func TestRevocationStatementTable(t *testing.T) {
	dir, keyHex, build, cases, _ := loadStatementTable(t)
	keys, err := parseHexKeys([]string{keyHex})
	if err != nil {
		t.Fatal(err)
	}
	sub := revocationSubject{manifest: build.Manifest, layer: build.Layer, predicate: build.Predicate, build: "20260101.000000", version: "26.8.15.10", platform: "linux-amd64"}
	verified := 0
	for _, c := range cases {
		rev, reason := verifyRevocation(statementBundle(t, dir, c.Bundle), keys, sub)
		switch c.Expect {
		case "verifies":
			if rev == nil {
				t.Errorf("%s: does not verify (%s), want it to", c.Name, reason)
				continue
			}
			verified++
			if len(rev.Advisories) != 1 || advisoryOf(rev.Advisories[0]) != c.ExpectAdvisory {
				t.Errorf("%s: advisory\n got %+v\nwant %+v", c.Name, rev.Advisories, c.ExpectAdvisory)
			}
			text := revokedText(sub, rev)
			if hasFix := c.ExpectAdvisory.SupersededBy != ""; hasFix != strings.Contains(text, "; superseded by build ") {
				t.Errorf("%s: message %q, superseded_by %q: the \"superseded by build\" part must appear exactly when there is a fix", c.Name, text, c.ExpectAdvisory.SupersededBy)
			}
		case "ignored":
			if rev != nil {
				t.Errorf("%s: verifies, want it refused", c.Name)
			} else if reason == "" {
				t.Errorf("%s: refused with no reason", c.Name)
			}
		default:
			t.Fatalf("%s: unknown expectation %q", c.Name, c.Expect)
		}
	}
	if verified == 0 {
		t.Fatal("no row verifies: the comparison above checked nothing")
	}
}

// referrerRegistry serves one build's referrers listing, in order, and each
// referrer's manifest and bundle. It returns the base and the manifest digest
// each bundle file was served under.
func referrerRegistry(t *testing.T, dir string, build statementBuild, referrers []string) (string, map[string]Digest) {
	t.Helper()
	var (
		mu      sync.Mutex
		objects = map[string][]byte{}
	)
	byFile := map[string]Digest{}
	idx := ImageIndex{SchemaVersion: 2, MediaType: MediaTypeIndex}
	// The listing must name a signature referrer, or the status is unread.
	idx.Manifests = append(idx.Manifests, Descriptor{MediaType: MediaTypeManifest, Digest: digestOf([]byte("signature")), Size: 9, ArtifactType: MediaTypeBundle})
	for _, name := range referrers {
		bundle := statementBundle(t, dir, name)
		layer := Descriptor{MediaType: MediaTypeBundle, Digest: digestOf(bundle), Size: int64(len(bundle))}
		empty := []byte("{}")
		mb, err := json.Marshal(ImageManifest{
			SchemaVersion: 2, MediaType: MediaTypeManifest, ArtifactType: RevocationArtifactType,
			Config: Descriptor{MediaType: "application/vnd.oci.empty.v1+json", Digest: digestOf(empty), Size: int64(len(empty))},
			Layers: []Descriptor{layer},
		})
		if err != nil {
			t.Fatal(err)
		}
		md := digestOf(mb)
		byFile[name] = md
		objects["manifests/"+string(md)] = mb
		objects["blobs/"+string(layer.Digest)] = bundle
		idx.Manifests = append(idx.Manifests, Descriptor{MediaType: MediaTypeManifest, Digest: md, Size: int64(len(mb)), ArtifactType: RevocationArtifactType})
	}
	listing, err := json.Marshal(idx)
	if err != nil {
		t.Fatal(err)
	}
	objects["referrers/"+string(build.Manifest)] = listing
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		defer mu.Unlock()
		for suffix, body := range objects {
			if strings.HasSuffix(r.URL.Path, "/"+suffix) {
				if strings.HasPrefix(suffix, "referrers/") {
					w.Header().Set("Content-Type", MediaTypeIndex)
				}
				_, _ = w.Write(body)
				return
			}
		}
		http.NotFound(w, r)
	}))
	t.Cleanup(srv.Close)
	return srv.URL + "/chtypes/v2", byFile
}

// TestRevocationListingTable: every listing row through the real candidate
// loop (CheckInstalled): the first verifying revocation wins, each ignored one
// is warned about, and with none verifying the build is allowed.
func TestRevocationListingTable(t *testing.T) {
	dir, keyHex, build, _, listings := loadStatementTable(t)
	defer UseProdV2ForTests()()
	revoked := 0
	for _, l := range listings {
		t.Run(l.Name, func(t *testing.T) {
			ResetRevocationMemoForTests()
			defer ResetRevocationMemoForTests()
			base, served := referrerRegistry(t, dir, build, l.Referrers)
			cache := t.TempDir()
			bdir := filepath.Join(cache, ProdV2CacheDir, UnpackedDirName(), build.Manifest.Hex())
			if err := os.MkdirAll(bdir, 0o755); err != nil {
				t.Fatal(err)
			}
			res := &Resolved{
				Platform: "linux-amd64", Request: "26.8", Version: "26.8.15.10", Build: "20260101.000000", Dir: bdir,
				Digests: Digests{Manifest: build.Manifest, Layer: build.Layer}, Predicate: build.Predicate,
			}
			w, err := CheckInstalled(context.Background(), res, &Options{Bases: []string{base}, CacheDir: cache, TrustedKeys: []string{keyHex}})

			skip := map[string]bool{}
			for _, f := range l.DontCare {
				skip[string(served[f])] = true
			}
			ignoredWarnings := 0
			for _, warning := range w {
				if !strings.Contains(warning, "does not verify and is ignored") {
					t.Errorf("unexpected warning %q", warning)
					continue
				}
				named := false
				for f, d := range served {
					if strings.Contains(warning, string(d)) && !skip[string(d)] {
						named = named || contains(l.Ignored, f)
					}
				}
				if !named && !anyIn(warning, skip) {
					t.Errorf("warning names no ignored referrer: %q", warning)
				}
				ignoredWarnings++
			}
			for _, f := range l.Ignored {
				found := false
				for _, warning := range w {
					found = found || strings.Contains(warning, string(served[f]))
				}
				if !found {
					t.Errorf("no warning names ignored referrer %s", f)
				}
			}
			if len(w) < len(l.Ignored) || ignoredWarnings-len(l.Ignored) > len(l.DontCare) {
				t.Errorf("%d warnings for %d ignored referrers (%d dont_care): %q", len(w), len(l.Ignored), len(l.DontCare), w)
			}

			switch l.Expect {
			case "revoked":
				var fe *FetchError
				if !errors.As(err, &fe) || fe.Code != CodeArtifactRevoked || fe.Revocation == nil || !fe.Revocation.Signed {
					t.Fatalf("got %v, want CHTYPES_ARTIFACT_REVOKED carrying a signed Revocation", err)
				}
				if len(fe.Revocation.Advisories) != 1 || advisoryOf(fe.Revocation.Advisories[0]) != l.ExpectAdvisory {
					t.Errorf("advisory\n got %+v\nwant %+v", fe.Revocation.Advisories, l.ExpectAdvisory)
				}
				revoked++
			case "fail-open":
				if err != nil {
					t.Fatalf("got %v, want the build allowed", err)
				}
			default:
				t.Fatalf("unknown expectation %q", l.Expect)
			}
		})
	}
	if revoked == 0 {
		t.Fatal("no listing revokes: the comparison above checked nothing")
	}
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

func anyIn(s string, set map[string]bool) bool {
	for d, on := range set {
		if on && strings.Contains(s, d) {
			return true
		}
	}
	return false
}
